// Moves the kept phases @ids past every position, so that rewriting them
// one by one never meets the unique position index.
func (q *Queries) ParkSubscriptionRatePhases(ctx context.Context, arg ParkSubscriptionRatePhasesParams) error {
	_, err := q.db.Exec(ctx, parkSubscriptionRatePhases, arg.OrganizationID, arg.SubscriptionRateCardID, arg.Ids)
	return err
}

